use vstd::prelude::*;
use vstd::string::*;

verus! {

spec fn is_lowercase_char(c: char) -> bool {
    c >= 'a' && c <= 'z'
}

spec fn all_lowercase(v: Seq<char>) -> bool {
    v.len() > 0 && forall|i: int| 0 <= i < v.len() ==> is_lowercase_char(v[i])
}

fn check_all_lowercase(v: &Vec<char>) -> (result: bool)
    ensures
        result == all_lowercase(v@),
{
    // First check if vector is empty
    if v.len() == 0 {
        return false;
    }
    
    let mut i: usize = 0;
    while i < v.len()
        invariant
            0 <= i <= v.len(),
            forall|j: int| 0 <= j < i ==> is_lowercase_char(v[j]),
        decreases v.len() - i,
    {
        let c = v[i];
        if !('a' <= c && c <= 'z') {
            return false;
        }
        i = i + 1;
    }
    
    true
}

fn solve(input: Vec<char>) -> (output: Vec<char>)
    ensures
        if all_lowercase(input@) {
            output@ == seq!['a']
        } else {
            output@ == seq!['A']
        },
{
    let all_lower = check_all_lowercase(&input);
    
    if all_lower {
        let mut result = Vec::new();
        result.push('a');
        result
    } else {
        let mut result = Vec::new();
        result.push('A');
        result
    }
}

}
